import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — DA-949, tích hợp DA-950","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/partner-directory/plan.md","filePath":"feature/media-package-campaign/partner-directory/plan.md"}'),c={name:"feature/media-package-campaign/partner-directory/plan.md"};function r(o,e,l,h,s,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="plan-—-da-949-tich-hop-da-950" tabindex="-1">Plan — DA-949, tích hợp DA-950 <a class="header-anchor" href="#plan-—-da-949-tich-hop-da-950" aria-label="Permalink to &quot;Plan — DA-949, tích hợp DA-950&quot;">​</a></h1><h2 id="_1-schema" tabindex="-1">1. Schema <a class="header-anchor" href="#_1-schema" aria-label="Permalink to &quot;1. Schema&quot;">​</a></h2><p>Viết migration mới thêm <code>is_active BOOLEAN NOT NULL DEFAULT TRUE</code>, <code>first_used_at TIMESTAMPTZ NULL</code> vào third_party_collaborators; đồng bộ init-postgres-v2.sql. Backfill first_used_at cho đối tác có link bằng mốc cập nhật sớm nhất hiện có (đây là lower-quality baseline, không khẳng định là thời điểm sử dụng thật đầu tiên). Bảo toàn mọi link và cooperation_status. Inventory dữ liệu lịch sử mất liên kết trước khi kết luận partner chưa từng dùng; hỏi team nếu không xác minh được.</p><h2 id="_2-service-api" tabindex="-1">2. Service/API <a class="header-anchor" href="#_2-service-api" aria-label="Permalink to &quot;2. Service/API&quot;">​</a></h2><p>Chi tiết đã chốt trước code: thêm <code>usage_history_verified BOOLEAN NOT NULL DEFAULT FALSE</code> cho legacy, API create đặt true; <code>version BIGINT NOT NULL DEFAULT 0</code> chống stale writes. DTO quản lý gồm canDelete + reason; contactInfo giữ JSONB object (API JSON object), UI nhập người liên hệ/email/điện thoại/website, giữ các keys legacy không biết khi sửa. Name trim/max255, notes max10000, contact JSON max10000 ký tự; fields lạ trên payload bị từ chối. Mutation có expectedVersion; deactivate lặp cùng trạng thái trả hiện tại. Schema trigger trên insert/link change khóa partner và chặn inactive; ghi firstUsedAt bền vững + version lần dùng đầu, bảo vệ cả writer cũ. Trigger không làm mới marker khi link/Campaign bị xóa. Marker mapped read-only trong JPA, không bị form overwrite. Lock assign Campaign→partner; CRUD lifecycle chỉ partner; cooperation update giữ link→partner read-only, không active gate cho link cũ. Không mở legacy CRUD stubs của FR 3.7.12; legacy assign/update đã delegate DA-950 và nhận cùng guard.</p><ul><li>Owner-only Agency CRUD/deactivate, chống cross-Agency, optimistic guard update. Reuse entity/repository, không gọi UnsupportedOperationException từ endpoint mới.</li><li>List management gồm inactive; Workspace selection list chỉ active, có quyền theo membership và không lộ toàn danh bạ sang Agency khác.</li><li>Lock row đối tác trong cả assign/delete/deactivate theo cùng thứ tự; verify active trước tạo link mới, update first_used_at cùng transaction. Delete chỉ khi first_used_at null VÀ không link, FK RESTRICT là lớp phòng thủ cuối.</li><li>Với link tồn tại, trả link idempotently trước active guard, không reset trạng thái. Inactive không chặn đọc/update cooperation link cũ.</li><li>Giữ legacy APIs nếu có consumer; đưa assign legacy qua cùng guard. Không cho payload sửa isActive/firstUsedAt trực tiếp; deactivate command riêng, không hỗ trợ reactivate trong đợt này.</li></ul><h2 id="_3-ui-va-pham-vi-file" tabindex="-1">3. UI và phạm vi file <a class="header-anchor" href="#_3-ui-va-pham-vi-file" aria-label="Permalink to &quot;3. UI và phạm vi file&quot;">​</a></h2><p>Owner route <code>/agency/:agencyId/collaborators</code>, form/list/detail và confirm actions tại feature riêng; typed API client. Thêm <code>src/i18n/locales/{vi,en}/collaborators.json</code> và đăng ký namespace. Chỉ thêm route/sidebar Owner cần thiết, không sửa menu/UI module khác. Workspace <code>pages/campaign-partners</code> dùng active picker; linked list hiện badge inactive. Locale <code>campaign.json</code> chỉ bổ sung keys liên quan. Theme tokens, focus, i18n, empty/retry/mobile/light-dark kiểm thử đầy đủ.</p><h2 id="_4-verify-rollback" tabindex="-1">4. Verify/rollback <a class="header-anchor" href="#_4-verify-rollback" aria-label="Permalink to &quot;4. Verify/rollback&quot;">​</a></h2><p>Unit/service tests và PostgreSQL integration race assign/delete/deactivate; legacy + Workspace APIs; browser flow thực. Migration rerun/parity test trên DB riêng, không chạy trên shared DB khi chưa có quyền. Rollback UI/API trước, giữ first_used_at và inactive data; không tự drop columns hoặc xóa lịch sử để quay về schema cũ. Commit schema/CRUD theo DA-949, Campaign guard/picker/regression theo DA-950.</p>',10)])])}const m=a(c,[["render",r]]);export{p as __pageData,m as default};
